// ─────────────────────────────────────────────────────────────────────────
// PLAYLIST DISCOVERY — connect real APIs here:
//   Spotify Web API  GET /v1/search?type=playlist  (SPOTIFY_CLIENT_ID/SECRET — backend/.env.example)
//   A curator-contact enrichment source for editorial/independent curator emails
// Until those credentials are connected this reports 'partial' with the
// specific missing credentials — it does not fabricate playlist data.
// Credential values are injected upstream by the 'Load Credential Flags'
// node (Set node expressions) since Code nodes cannot access $env directly.
// ─────────────────────────────────────────────────────────────────────────
const input = $input.first().json;
const missing = [];
if (!input.SPOTIFY_CLIENT_ID || !input.SPOTIFY_CLIENT_SECRET) missing.push('SPOTIFY_CLIENT_ID', 'SPOTIFY_CLIENT_SECRET');

return [{ json: {
  mission_id: input.mission_id,
  execution_id: input.execution_id,
  status: missing.length ? 'partial' : 'completed',
  summary: missing.length ? `Playlist Intelligence ready — waiting on: ${missing.join(', ')}` : 'Playlist discovery complete',
  results: {
    playlists_found: null,
    editorial_opportunities: null,
    curator_contacts: null,
    priority_playlists: null,
    genre_matching: input.context?.genre ?? input.release?.genre ?? null,
    acceptance_probability: null,
    missing_credentials: missing,
  },
} }];
